const int NUM_ROM_IMAGES = 1;

static const unsigned short* image_cache[] = {
    DukeTango
};

static const int image_size[] = {
    sizeof(DukeTango)
};

/**
 * Loads a native image from rom, if present.
 *
 * @param imageId    The image id
 * @param **bufPtr   Pointer where a buffer will be allocated and data stored
 * @return           -1 if failed, else length of buffer
 */
int loadImageFromRom(int imageId, unsigned char** bufPtr) {

    int len = -1;
    if ((imageId < 0) || (imageId > NUM_ROM_IMAGES)) {
        return len;
    }

    *bufPtr = (unsigned char*)image_cache[imageId];
    len = image_size[imageId];
    return len;
}

